from collections.abc import Mapping
from typing import Any
import os

def load_settings(schema: Mapping[str, tuple[Callable[[str], Any], Any]], env: Mapping[str, str] | None=None, secret_names: tuple[str, ...]=()) -> dict[str, Any]:
    env = os.environ if env is None else env
    settings: dict[str, Any] = {}
    errors: list[str] = []
    for name, (parser, default) in schema.items():
        raw = env.get(name)
        if raw is None:
            if default is ...:
                errors.append(f'{name} is required')
            else:
                settings[name.lower()] = default
            continue
        try:
            settings[name.lower()] = parser(raw)
        except (ValueError, TypeError) as exc:
            errors.append(f'{name}: invalid value' if name in secret_names else f'{name}: {exc}')
    if errors:
        raise ValueError('invalid configuration:\n- ' + '\n- '.join(errors))
    return settings

def parse_bool(raw: str) -> bool:
    value = raw.strip().lower()
    if value in ('1', 'true', 'yes', 'on'):
        return True
    if value in ('0', 'false', 'no', 'off'):
        return False
    raise ValueError(f'expected a boolean, got {raw!r}')

def parse_port(raw: str) -> int:
    try:
        port = int(raw.strip())
    except ValueError:
        raise ValueError(f'expected an integer port, got {raw!r}') from None
    if not 1 <= port <= 65535:
        raise ValueError(f'port must be between 1 and 65535, got {port}')
    return port

def parse_database_url(raw: str) -> str:
